"""Cron job that aggregates the previous day's fuzzer statistics and loads
them into a BigQuery data warehouse."""

import argparse
import datetime
import io
import json

from googleapiclient.errors import HttpError
from googleapiclient.http import MediaIoBaseUpload

from clusterfuzz._internal.base import utils
from clusterfuzz._internal.google_cloud_utils import big_query
from clusterfuzz._internal.metrics import logs

# BigQuery destination for the aggregated stats.
DATASET_ID = 'fuzzer_stats'
TABLE_ID = 'daily_stats'

# Ordered list of fields uploaded for each aggregated record.
STATS_FIELDS = [
    'fuzzer_name',
    'date',
    'testcases_executed',
    'testcase_execution_duration',
    'testcases_generated',
    'testcase_generation_duration',
    'fuzzing_duration',
]

# Schema for the 'daily_stats' table. The table is partitioned by day on the
# 'date' field.
DAILY_STATS_SCHEMA = {
    'fields': [
        {
            'name': 'fuzzer_name',
            'type': 'STRING',
            'mode': 'NULLABLE',
        },
        {
            'name': 'date',
            'type': 'DATE',
            'mode': 'NULLABLE',
        },
        {
            'name': 'testcases_executed',
            'type': 'INTEGER',
            'mode': 'NULLABLE',
        },
        {
            'name': 'testcase_execution_duration',
            'type': 'FLOAT',
            'mode': 'NULLABLE',
        },
        {
            'name': 'testcases_generated',
            'type': 'INTEGER',
            'mode': 'NULLABLE',
        },
        {
            'name': 'testcase_generation_duration',
            'type': 'FLOAT',
            'mode': 'NULLABLE',
        },
        {
            'name': 'fuzzing_duration',
            'type': 'FLOAT',
            'mode': 'NULLABLE',
        },
    ],
}

# Query used to aggregate the previous day's fuzzer statistics. The date filter
# selects rows whose UNIX timestamp falls on the target day.
QUERY_FORMAT = """
SELECT
  fuzzer AS fuzzer_name,
  '{date}' AS date,
  SUM(testcases_executed) AS testcases_executed,
  SUM(testcase_execution_duration) AS testcase_execution_duration,
  SUM(testcases_generated) AS testcases_generated,
  SUM(testcase_generation_duration) AS testcase_generation_duration,
  SUM(fuzzing_duration) AS fuzzing_duration
FROM
  TestcaseRun
WHERE
  DATE(TIMESTAMP_SECONDS(CAST(timestamp AS INT64))) = '{date}'
GROUP BY
  fuzzer
""".strip()


def _utc_now():
  """Return datetime.datetime.utcnow()."""
  return datetime.datetime.utcnow()


def _valid_date(value):
  """argparse type that validates a YYYY-MM-DD date string."""
  try:
    return datetime.datetime.strptime(value, '%Y-%m-%d').date()
  except ValueError:
    raise argparse.ArgumentTypeError(
        f'Invalid date {value!r}, expected format YYYY-MM-DD.')


def _parse_args(args):
  """Parse command-line arguments."""
  parser = argparse.ArgumentParser(
      description='Aggregate daily fuzzer stats into BigQuery.')
  parser.add_argument(
      '--non-dry-run',
      action='store_true',
      help='If set, perform write operations against BigQuery.')
  parser.add_argument(
      '--date',
      type=_valid_date,
      default=None,
      help='Target date (YYYY-MM-DD) to aggregate. Defaults to yesterday.')
  return parser.parse_args(args)


def _create_dataset_if_needed(bigquery, project_id):
  """Create the destination dataset, ignoring 'already exists' errors."""
  dataset_body = {
      'datasetReference': {
          'projectId': project_id,
          'datasetId': DATASET_ID,
      },
  }

  try:
    bigquery.datasets().insert(
        projectId=project_id, body=dataset_body).execute()
  except HttpError as e:
    if e.resp.status == 409:
      # Dataset already exists; nothing to do.
      logs.info(f'Dataset {DATASET_ID} already exists.')
      return

    # Any other error is unexpected and should propagate.
    raise


def _create_table_if_needed(bigquery, project_id):
  """Create the destination table if it does not already exist."""
  table_body = {
      'tableReference': {
          'projectId': project_id,
          'datasetId': DATASET_ID,
          'tableId': TABLE_ID,
      },
      'timePartitioning': {
          'type': 'DAY',
          'field': 'date',
      },
      'schema': DAILY_STATS_SCHEMA,
  }

  try:
    bigquery.tables().insert(
        projectId=project_id, datasetId=DATASET_ID, body=table_body).execute()
  except HttpError as e:
    if e.resp.status == 409:
      # Table already exists; nothing to do.
      logs.info(f'Table {TABLE_ID} already exists.')
      return

    raise


def _extract_rows(response):
  """Extract query result rows as a list of dicts."""
  if not response:
    return []

  rows = response.get('rows', [])
  schema = response.get('schema') or {}
  fields = schema.get('fields')

  results = []
  for row in rows:
    # Support both the raw BigQuery {'f': [{'v': ...}]} row format and rows
    # that are already dicts keyed by field name.
    if isinstance(row, dict) and 'f' in row and fields:
      results.append(big_query.convert_row(row, fields))
    else:
      results.append(row)

  return results


def _query_daily_stats(bigquery, project_id, date_string):
  """Query the aggregated fuzzer stats for the target date."""
  query = QUERY_FORMAT.format(date=date_string)
  body = {
      'query': query,
      'useLegacySql': False,
  }

  response = bigquery.jobs().query(projectId=project_id, body=body).execute()
  return _extract_rows(response)


def _upload_stats(bigquery, project_id, date_compact, rows):
  """Load the aggregated stats into the daily partition of the table."""
  records = []
  for row in rows:
    record = {field: row.get(field) for field in STATS_FIELDS}
    records.append(json.dumps(record))

  data = '\n'.join(records)
  media_body = MediaIoBaseUpload(
      io.BytesIO(data.encode('utf-8')),
      mimetype='application/octet-stream',
      resumable=True)

  job_body = {
      'configuration': {
          'load': {
              'destinationTable': {
                  'projectId': project_id,
                  'datasetId': DATASET_ID,
                  'tableId': f'{TABLE_ID}${date_compact}',
              },
              'sourceFormat': 'NEWLINE_DELIMITED_JSON',
              'writeDisposition': 'WRITE_TRUNCATE',
              'schema': DAILY_STATS_SCHEMA,
          },
      },
  }

  logs.info('Uploading aggregated fuzzer stats to BigQuery.', job_body=job_body)
  bigquery.jobs().insert(
      projectId=project_id, body=job_body, media_body=media_body).execute()


